import { Sim } from "../src/sim";
import { PRESETS } from "../src/presets";

const duration = 1500;
const every = 50;
const only = (globalThis as { process?: { argv: string[] } }).process?.argv[2];
const seeds = [7, 11, 23];

for (const preset of PRESETS) {
  if (only && preset.id !== only) continue;
  for (const seed of seeds) {
    const sim = new Sim({ ...preset.params, seed });
    const rows: string[] = [];
    const t0 = performance.now();
    while (sim.time < duration) {
      sim.step();
      sim.events.length = 0;
      if (Math.abs(sim.time % every) < Sim.DT / 2) {
        const c = sim.counts();
        rows.push(`${c.blue}/${c.red}/${sim.totalFruit()}`);
      }
    }
    const ms = (performance.now() - t0).toFixed(0);
    console.log(`${preset.id.padEnd(9)} s${seed} ${ms}ms  ${rows.join(" ")}`);
  }
}

