      acts[`${b.kind[0]}:${b.action}`] = (acts[`${b.kind[0]}:${b.action}`] ?? 0) + 1;
      if (b.kind === "blue") e += b.energy;
    }
    const ev: Record<string, number> = {};
    for (const x of sim.events) ev[x.type] = (ev[x.type] ?? 0) + 1;
    sim.events.length = 0;
    console.log(sim.time.toFixed(1), c, "fruit", sim.totalFruit(), "avgE", (e / (c.blue || 1)).toFixed(1), JSON.stringify(acts), JSON.stringify(ev));
  }
}

