args.streamContent:
import { Sim, DEFAULTS, TUNING } from "../src/sim";

const argv = (globalThis as { process?: { argv: string[] } }).process?.argv ?? [];
const over = argv[2] ? JSON.parse(argv[2]) : {};
if (argv[3]) Object.assign(TUNING, JSON.parse(argv[3]));

const sim = new Sim({ ...DEFAULTS, ...over });
let tick = 0;
let tags = 0;
let chaseTicks = 0;
let redTicks = 0;
while (sim.time < 120) {
  sim.step();
  tick++;
  for (const e of sim.events) if (e.type === "tag") tags++;
  sim.events.length = 0;
  for (const b of sim.blobs)
    if (b.kind === "red") {
      redTicks++;
      if (b.action === "chasing") chaseTicks++;
    }
  if (tick % 400 === 0) {
    const c = sim.counts();
    const acts: Record<string, number> = {};
    let e = 0;
    let hid = 0;
    for (const b of sim.blobs) {
      acts[`${b.kind[0]}:${b.action}`] = (acts[`${b.kind[0]}:${b.action}`] ?? 0) + 1;
      if (b.kind === "red") e += b.energy;
      if (b.hidden) hid++;
    }
    const redSec = (redTicks * Sim.DT) || 1;
    console.log(
      sim.time.toFixed(0),
      c,
      "redE",
      (e / (c.red || 1)).toFixed(1),
      "tags/red/s",
      (tags / redSec).toFixed(3),
      "chase%",
      ((chaseTicks / (redTicks || 1)) * 100).toFixed(0),
      "hidden",
      hid,
      JSON.stringify(acts),
    );
    tags = chaseTicks = redTicks = 0;
  }
}

