+  private drawTree(t: Tree, sim: Sim) {
+    const ctx = this.ctx;
+    const [sx, sy] = this.project(t.x, t.y);
+    const u = this.scale * t.size;
+    const lift = 0.45 + 0.55 * this.hf;
+    const sway = Math.sin(this.clock * 1.3 + t.id * 1.7) * 0.04 * u;
