+    if (b.action === "resting") stretch = 1 + Math.sin(this.clock * 6) * 0.05;
+    if (b.action === "dozing") stretch = 0.92 + Math.sin(this.clock * 1.4 + b.seed * 5) * 0.03;
+    const [dxs, dys] = this.screenDir(b.heading);
