+    ctx.beginPath();
+    ctx.ellipse(0, -h, w, h, 0, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.strokeStyle = pal.line;
+    ctx.lineWidth = 1;
+    ctx.stroke();
+    // Gloss.
+    ctx.fillStyle = "rgba(255,255,255,0.55)";
+    ctx.beginPath();
