+      ctx.fill();
+    } else if (scared) {
+      ctx.beginPath();
+      ctx.ellipse(fx, my, er * 0.32, er * 0.42, 0, 0, Math.PI * 2);
+      ctx.fill();
+      // Sweat drop.
+      ctx.fillStyle = "rgba(170,220,255,0.95)";
+      ctx.beginPath();
+      ctx.ellipse(fx + w * 0.75, fy - h * 0.25, w * 0.08, w * 0.13, 0, 0, Math.PI * 2);
+      ctx.fill();
+    } else if (a === "chasing") {
+      ctx.beginPath();
+      ctx.arc(fx, my - er * 0.4, er * 0.6, Math.PI * 0.15, Math.PI * 0.85);
