+    } else if (sleepy) {
+      ctx.beginPath();
+      ctx.arc(fx, my, er * 0.22, 0, Math.PI * 2);
+      ctx.stroke();
+    } else {
+      ctx.beginPath();
+      ctx.arc(fx, my - er * 0.45, er * 0.5, Math.PI * 0.2, Math.PI * 0.8);
+      ctx.stroke();
+    }
+  }
+
+  private drawGhost(g: Ghost) {
+    const ctx = this.ctx;
+    const [sx, sy] = this.project(g.x, g.y);
