  ctx.lineWidth = width;
  ctx.lineJoin = "round";
  ctx.beginPath();
  let started = false;
  for (const s of pts) {
    const y = fy(s);
    if (!Number.isFinite(y)) {
      started = false;
      continue;
    }
    if (!started) {
