      else hi = mid;
    }
    s = hist[lo];
    const x = X(s.t);
    ctx.strokeStyle = "rgba(60,40,20,0.35)";
    ctx.beginPath();
    ctx.moveTo(x, T);
    ctx.lineTo(x, T + H);
