:root {
  --bg: #f5ecdc;
  --card: #fffaf1;
  --ink: #3b3127;
  --muted: #8a7a66;
  --line: rgba(90, 60, 30, 0.12);
  --blue: #2f7fe0;
  --red: #e5484d;
  --fruit: #58a83a;
  --accent: #f08a3c;
  --radius: 18px;
  font-family: ui-rounded, "SF Pro Rounded", "Nunito", system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--bg);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 20% -10%, #fff6e6 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #fde3c8 0%, transparent 60%),
    var(--bg);
}

#app {
  max-width: 1680px;
  margin: 0 auto;
  padding: 14px 18px 28px;
}

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

h1 {
  margin: 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.stats {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.stat {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 12px;
  font-size: 13px;
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-variant-numeric: tabular-nums;
}

.stat b {
  font-size: 15px;
}

.stat.blue b {
  color: var(--blue);
}
.stat.red b {
  color: var(--red);
}
.stat.fruit b {
  color: var(--fruit);
}
.stat span {
  color: var(--muted);
}

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  grid-template-areas:
    "stage panel"
    "charts panel";
  gap: 14px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 8px 24px -12px rgba(90, 60, 30, 0.25);
}

.stage {
  grid-area: stage;
  position: relative;
  height: min(66vh, 720px);
  min-height: 440px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 35%, #fff8ea 0%, #f7e7cf 70%, #f0dcc0 100%);
}

#world {
  width: 100%;
  height: 100%;
  display: block;
  cursor: grab;
  touch-action: none;
}

#world.dragging {
  cursor: grabbing;
}

#world.pointing {
  cursor: pointer;
}

.transport {
  position: absolute;
  left: 14px;
  bottom: 14px;
  display: flex;
  gap: 6px;
  align-items: center;
  background: rgba(255, 250, 241, 0.88);
  backdrop-filter: blur(8px);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 6px;
}

.btn {
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  border-radius: 10px;
  padding: 7px 12px;
  cursor: pointer;
  transition: transform 0.08s, background 0.15s;
}

.btn:hover {
  background: #fff3e2;
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn.primary {
  background: var(--accent);
  border-color: #d97026;
  color: #fff;
  min-width: 74px;
}

.btn.primary:hover {
  background: #f39a52;
}

.btn.pending {
  background: #fff1c2;
  border-color: #e7b93f;
  animation: nudge 1.4s ease-in-out infinite;
}

@keyframes nudge {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(231, 185, 63, 0.5);
  }
  50% {
    box-shadow: 0 0 0 5px rgba(231, 185, 63, 0);
  }
}

.speed {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
