  color: var(--ink);
  min-width: 34px;
  font-variant-numeric: tabular-nums;
}

.legend {
  position: absolute;
  right: 14px;
  bottom: 14px;
  display: flex;
  gap: 10px;
  font-size: 12px;
  color: var(--muted);
