  font-weight: 700;
}

.fate {
  margin-top: 8px;
  font-weight: 700;
  color: #9b4a1c;
}

.panel {
  grid-area: panel;
  padding: 14px;
  align-self: start;
  position: sticky;
  top: 14px;
  max-height: calc(100vh - 28px);
  overflow-y: auto;
}

.panel h2 {
  font-size: 14px;
  margin: 0 0 8px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.preset {
  font: inherit;
  font-size: 12.5px;
  font-weight: 700;
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 999px;
  padding: 6px 11px;
  cursor: pointer;
}

.preset:hover {
  background: #fff3e2;
}

.preset.active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.preset-blurb {
  font-size: 12.5px;
  color: var(--muted);
  margin: 8px 2px 4px;
  min-height: 2.6em;
}

.group {
  border-top: 1px solid var(--line);
  padding-top: 10px;
  margin-top: 10px;
}

.group h3 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  margin: 0 0 6px;
}

.group h3 .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.group h3 .tag {
  font-size: 10.5px;
  font-weight: 700;
  color: #9b7a2a;
  background: #fff1c2;
  border-radius: 999px;
  padding: 1px 7px;
  margin-left: auto;
}

.ctl {
  padding: 4px 0 2px;
}

.ctl .row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 12.5px;
}

.ctl .row label {
  font-weight: 600;
}

.ctl .row output {
  font-variant-numeric: tabular-nums;
  font-weight: 800;
  font-size: 12.5px;
}

.ctl .desc {
  font-size: 11px;
  color: var(--muted);
  margin-top: -1px;
}

.ctl.changed .row output {
  color: #c06a12;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
  margin: 3px 0 0;
}

.group.blue input[type="range"] {
  accent-color: var(--blue);
}
.group.red input[type="range"] {
  accent-color: var(--red);
}
.group.fruit input[type="range"] {
  accent-color: var(--fruit);
}

.seed-row {
  display: flex;
  gap: 6px;
  align-items: center;
  margin-top: 6px;
  font-size: 12.5px;
}

.seed-row label {
  font-weight: 600;
  flex: 1;
}

.seed-row input {
  width: 90px;
  font: inherit;
  font-size: 13px;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.charts {
  grid-area: charts;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.charts .card {
  padding: 12px 14px;
}

.chart-main {
  grid-column: 1 / -1;
}

.chart-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
  flex-wrap: wrap;
}

.chart-head h3 {
  margin: 0;
  font-size: 14px;
}

.chart-legend {
  display: flex;
  gap: 12px;
  font-size: 12px;
  color: var(--muted);
}

.chart-legend span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.ln {
  width: 16px;
  height: 3px;
  border-radius: 2px;
  display: inline-block;
}
.ln.blue {
  background: var(--blue);
}
.ln.red {
  background: var(--red);
}
.ln.fruit {
  background: var(--fruit);
}

.chart-wrap {
  position: relative;
}

#timeline {
  width: 100%;
  height: 220px;
  display: block;
}

canvas.small {
  width: 100%;
  height: 170px;
  display: block;
}

.caption {
  font-size: 11.5px;
  color: var(--muted);
  margin: 6px 0 0;
}

.tip {
  position: absolute;
  top: 6px;
  pointer-events: none;
  background: rgba(59, 49, 39, 0.92);
  color: #fff;
  font-size: 12px;
  padding: 6px 9px;
  border-radius: 9px;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.tip b.blue {
  color: #9fd0ff;
}
.tip b.red {
  color: #ffa7a9;
}
.tip b.fruit {
  color: #c4f08f;
}

.summary #summary h4 {
  margin: 2px 0 8px;
  font-size: 17px;
}

.summary ul {
  margin: 0;
  padding-left: 18px;
  font-size: 13px;
  line-height: 1.45;
}

.summary li {
  margin-bottom: 5px;
}

.mood {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 999px;
  padding: 2px 8px;
  background: #efe4d2;
}

.mood.wavy,
.mood.balanced {
  background: #dff3d4;
  color: #2f6b1f;
}
.mood.boom {
  background: #ffe2c2;
  color: #a2510f;
}
.mood.faded,
.mood.empty {
  background: #f1dede;
  color: #8a2b2b;
}
.mood.small {
  background: #e3ecf8;
  color: #2c4f80;
}

@media (max-width: 1100px) {
  .layout {
    grid-template-columns: 1fr;
    grid-template-areas:
      "stage"
      "panel"
      "charts";
  }
  .panel {
    position: static;
    max-height: none;
  }
  .charts {
    grid-template-columns: 1fr;
  }
  .legend {
    display: none;
  }
}

