      { key: "redSpeed", label: "Speed", desc: "Chase speed (faster costs more energy)", min: 1, max: 6, step: 0.1, fmt: un },
      { key: "redVision", label: "Vision", desc: "How far they spot blues in the open", min: 2, max: 16, step: 0.5, fmt: un },
