+      <span>Speed</span><b>${now.toFixed(1)} now · ${speed.toFixed(2)} max</b>
+      <span>Sensing range</span><b>${vision.toFixed(1)}</b>
+      <span>Speed gene</span><b>${pct(b.gSpeed)}</b>
